import{_ as s,a0 as p,w as i,s as u,ao as a,I as r,a1 as n,A as e,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"為你的開源項目舉辦一場文檔馬拉松 | LCTT x X-CMD","titleTemplate":false,"description":"為你的開源項目舉辦一場文檔馬拉松 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為你的開源項目舉辦一場文檔馬拉松 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為你的開源項目舉辦一場文檔馬拉松 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project","title":"為你的開源項目舉辦一場文檔馬拉松","tag":"202306","desc":""},"relativePath":"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project.md","filePath":"[post].md"}'),d={name:"202306/20230428.2 ⭐️⭐️ 3 reasons to host a docathon for your open source project.md"};function f(m,t,b,T,g,k){const l=p("Link");return i(),u("div",null,[t[29]||(t[29]=a('<h1 id="為你的開源項目舉辦一場文檔馬拉松" tabindex="-1">為你的開源項目舉辦一場文檔馬拉松 <a class="header-anchor" href="#為你的開源項目舉辦一場文檔馬拉松" aria-label="Permalink to “為你的開源項目舉辦一場文檔馬拉松”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/02/001044rfszwiujown8fd3j.jpg" alt=""></p><blockquote><p>文檔馬拉松是為你的開源項目製作或改進文檔的一個好方法。</p></blockquote><p>你的開源項目的文檔對你的客户至關重要。你的目標受眾必須瞭解你的項目的目的和如何使用它，而文檔是彌合這一差距的工具。一個項目很少有真正完成的時候，所以隨着你項目的不斷改進，資源的維護和更新同樣重要。</p><p>但是，當你有大量的文檔需要維護，但又缺乏資源來保持它的時效性時，會發生什麼？答案很簡單：舉辦一個 <ruby>文檔馬拉松<rt>docathon</rt></ruby>！</p><h3 id="什麼是文檔馬拉松" tabindex="-1">什麼是文檔馬拉松？ <a class="header-anchor" href="#什麼是文檔馬拉松" aria-label="Permalink to “什麼是文檔馬拉松？”">​</a></h3><p>文檔馬拉松就像 <ruby>黑客馬拉松<rt>hackathon</rt></ruby>。黑客馬拉松是工程師和社區領袖聚集在一起改進或添加新功能到一個現有的應用的活動。在一個文檔馬拉松中，同樣的合作集中在改進文檔上。</p><p>文檔馬拉松可以填補內容上的空白，重組大型文檔集，修復失效的鏈接，或者只是糾正錯別字。舉辦文檔馬拉松的目的是為了在相對短的時間內改進大量的文檔。</p><p>一些產品文檔的例子包括：</p>',9)),r("ul",null,[t[2]||(t[2]=r("li",null,"培訓手冊",-1)),t[3]||(t[3]=r("li",null,"用户手冊",-1)),t[4]||(t[4]=r("li",null,"安裝指南",-1)),t[5]||(t[5]=r("li",null,"故障排除指南",-1)),t[6]||(t[6]=r("li",null,"快速入門指南",-1)),r("li",null,[n(l,{href:"https://www.redhat.com/en/topics/api/what-are-application-programming-interfaces?intcmp=7013a000002qLH8AAM"},{default:e(()=>[...t[0]||(t[0]=[o("API",-1)])]),_:1}),t[1]||(t[1]=o(" 文檔",-1))]),t[7]||(t[7]=r("li",null,"教程",-1))]),t[30]||(t[30]=r("p",null,"在我的組織里，我們的文檔團隊舉辦了一次文檔馬拉松，成功地修改了 102 頁的安裝指南。這次文檔馬拉松使我們能夠專注於項目的範圍，即重新組織簡化，刪除重複的內容，並遵循客户旅程。舉辦文檔馬拉松給我的團隊留下了深刻的印象，並提高了客户的成功率。",-1)),t[31]||(t[31]=r("h3",{id:"_3-件你可以通過文檔馬拉松實現的事情",tabindex:"-1"},[o("3 件你可以通過文檔馬拉松實現的事情 "),r("a",{class:"header-anchor",href:"#_3-件你可以通過文檔馬拉松實現的事情","aria-label":"Permalink to “3 件你可以通過文檔馬拉松實現的事情”"},"​")],-1)),t[32]||(t[32]=r("p",null,"以下是我舉辦文檔馬拉松的三大理由：",-1)),t[33]||(t[33]=r("h4",{id:"_1、減少積壓",tabindex:"-1"},[o("1、減少積壓 "),r("a",{class:"header-anchor",href:"#_1、減少積壓","aria-label":"Permalink to “1、減少積壓”"},"​")],-1)),r("p",null,[t[9]||(t[9]=o("大多數文檔必須隨着它所支持的產品的發展而發展。隨着產品的變化或更新，文檔也必須如此。在某些情況下，文檔團隊與工程團隊的發佈週期一起發佈新版本的文檔。隨着團隊內優先級的改變和 ",-1)),n(l,{href:"https://opensource.com/article/19/7/what-golden-image"},{default:e(()=>[...t[8]||(t[8]=[o("GA 發佈",-1)])]),_:1}),t[10]||(t[10]=o(" 的繼續，文檔團隊面臨着跟上新功能、錯誤修復和任務完成的挑戰。被遺棄的變化成為積壓的一部分，一種需要在以後完成的工作的積累。",-1))]),t[34]||(t[34]=a('<blockquote><p><strong>提示：</strong> 在文檔馬拉松期間，參與者可以對積壓的項目進行分流，並在列表中完成它們。非技術性的參與者可以從事與錯別字、失效的鏈接和其他文本相關問題的修復工作。</p></blockquote><h4 id="_2、改造大型指南" tabindex="-1">2、改造大型指南 <a class="header-anchor" href="#_2、改造大型指南" aria-label="Permalink to “2、改造大型指南”">​</a></h4><p>當你的文檔團隊意識到是時候修改指南的時候，它可能已經有好幾章，好幾百頁了。一旦制定了內容計劃，重組的複雜性就開始了。重組大量的文檔並不適合膽小的人。</p><blockquote><p><strong>提示：</strong> 組建一個團隊來領導文檔馬拉松，併為不同團隊或部門的全組織參與提供獎勵。根據工作範圍和時間限制，你的團隊可以在比你預期更短的時間內成功重組整個指南。</p></blockquote><h4 id="_3、跨職能團隊之間的合作" tabindex="-1">3、跨職能團隊之間的合作 <a class="header-anchor" href="#_3、跨職能團隊之間的合作" aria-label="Permalink to “3、跨職能團隊之間的合作”">​</a></h4><p>一個組織內的不同小組孤立地工作是很常見的。工程、產品、客户支持、營銷和文檔團隊可能沒有像他們應該的那樣經常在項目上進行協作。</p><p>想像一下，舉辦一次活動，每個團隊成員都可以利用他們的專業知識來改善產品文檔。文檔馬拉松促進了主題專家（SME）的多樣性、實時協作和溝通。它們還允許一個包容性的環境，居住在不同地理位置的人可以親自或遠程參與。你的文件會得到具有不同觀點和專業的專家的關注，最大限度地減少孤立的孤島、無意識的偏見和倦怠。</p><blockquote><p><strong>提示：</strong> 使跨職能的團隊為了一個共同的事業走到一起。</p></blockquote><h3 id="文檔馬拉松" tabindex="-1">文檔馬拉松 <a class="header-anchor" href="#文檔馬拉松" aria-label="Permalink to “文檔馬拉松”">​</a></h3>',9)),r("p",null,[t[12]||(t[12]=o("下一次，當你的團隊有一個似乎無法克服的積壓工作，或者被賦予重組一個巨大的文檔項目的任務時，考慮舉辦一個文檔馬拉松。這很容易，而且它的生產力可能會讓你吃驚。關於舉辦這樣的活動的更多信息，請閲讀 Tiffany Long 寫的很棒的 ",-1)),n(l,{href:"https://opensource.com/downloads/hackathon-guide?intcmp=7013a000002qLH8AAM"},{default:e(()=>[...t[11]||(t[11]=[o("舉辦黑客馬拉松的 10 步指南",-1)])]),_:1}),t[13]||(t[13]=o("。",-1))]),t[35]||(t[35]=r("p",null,[r("em",null,"（題圖：MJ/1284f6fb-91e9-4799-8773-ee7f51fd87c9）")],-1)),t[36]||(t[36]=r("hr",null,null,-1)),r("p",null,[t[15]||(t[15]=o("via: ",-1)),n(l,{href:"https://opensource.com/article/23/4/open-source-docathon"},{default:e(()=>[...t[14]||(t[14]=[o("https://opensource.com/article/23/4/open-source-docathon",-1)])]),_:1})]),r("p",null,[t[20]||(t[20]=o("作者：",-1)),n(l,{href:"https://opensource.com/users/lmalivert"},{default:e(()=>[...t[16]||(t[16]=[o("Lydie Modé-Malivert",-1)])]),_:1}),t[21]||(t[21]=o(" 選題：",-1)),n(l,{href:"https://github.com/lkxed/"},{default:e(()=>[...t[17]||(t[17]=[o("lkxed",-1)])]),_:1}),t[22]||(t[22]=o(" 譯者：",-1)),n(l,{href:"https://github.com/geekpi"},{default:e(()=>[...t[18]||(t[18]=[o("geekpi",-1)])]),_:1}),t[23]||(t[23]=o(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:e(()=>[...t[19]||(t[19]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[24]||(t[24]=[o("LCTT",-1)])]),_:1}),t[27]||(t[27]=o(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:e(()=>[...t[25]||(t[25]=[o("Linux中國",-1)])]),_:1}),t[28]||(t[28]=o(" 榮譽推出",-1))])])}const L=s(d,[["render",f]]);export{P as __pageData,L as default};
